// server.js - Add robust error handling
util = require('util');
EventEmitter = require('events').EventEmitter;
net = require('net');
extend = require('node.extend');
functions = require('./functions');
Device = require('./device');

util.inherits(Server, EventEmitter);

function Server(opts, callback) {
  if (!(this instanceof Server)) {
    return new Server(opts, callback);
  }

  EventEmitter.call(this);
  var defaults = {
    debug: false,
    port: 8080,
    device_adapter: false,
    maxConnections: 1000,
    connectionTimeout: 30000, // 30 seconds
    keepAlive: true,
  };

  // Merge default options with user options
  this.opts = extend(defaults, opts);

  var _this = this;
  this.devices = [];
  this.connectionCount = 0;

  this.server = false;
  this.availableAdapters = {
    TK103: './adapters/tk103',
    TK510: './adapters/tk510',
    GT02A: './adapters/gt02a',
    GT06: './adapters/gt06',
    GT06N: './adapters/gt06',
  };

  /****************************
   SOME FUNCTIONS
   *****************************/
  /* */
  this.setAdapter = function (adapter) {
    if (typeof adapter.adapter !== 'function') {
      throw 'The adapter needs an adapter() method to start an instance of it';
    }

    this.device_adapter = adapter;
  };

  this.getAdapter = function () {
    return this.device_adapter;
  };

  this.addAdaptar = function (model, Obj) {
    this.availableAdapters.push(model);
  };

  this.init = function (cb) {
    // Set debug
    _this.setDebug(this.opts.debug);

    /*****************************
     DEVICE ADAPTER INITIALIZATION
     ******************************/
    if (_this.opts.device_adapter === false)
      throw 'The app don\'t set the device_adapter to use. Which model is sending data to this server?';

    if (typeof _this.opts.device_adapter === 'string') {

      // Check if the selected model has an available adapter registered
      if (typeof this.availableAdapters[this.opts.device_adapter] === 'undefined')
        throw 'The class adapter for ' + this.opts.device_adapter + ' doesn\'t exists';

      // Get the adapter
      var adapterFile = (this.availableAdapters[this.opts.device_adapter]);

      this.setAdapter(require(adapterFile));

    } else {
      // IF THE APP PASS THE ADEPTER DIRECTLY
      _this.setAdapter(this.opts.device_adapter);
    }

    _this.emit('before_init');
    if (typeof cb === 'function') cb();
    _this.emit('init');

    /* FINAL INIT MESSAGE */
    console.log('\n=================================================\nGPS LISTENER running at port ' + _this.opts.port + '\nEXPECTING DEVICE MODEL:  ' + _this.getAdapter().model_name + '\n=================================================\n');
  };

  this.do_log = function (msg, from) {
    // If debug is disabled, return false
    if (this.getDebug() === false) return false;

    // If from parameter is not set, default is server.
    if (typeof from === 'undefined') {
      from = 'SERVER';
    }

    msg = '#' + from + ': ' + msg;
    console.log(msg);
  };

  /****************************************
   SOME SETTERS & GETTERS
   ****************************************/
  this.setDebug = function (val) {
    this.debug = (val === true);
  };

  this.getDebug = function () {
    return this.debug;
  };

  // Init app
  this.init(function () {
    /*************************************
     AFTER INITIALIZING THE APP...
     *************************************/
    _this.server = net.createServer(function (connection) {
      // Connection limit check
      _this.connectionCount++;
      if (_this.connectionCount > _this.opts.maxConnections) {
        console.log('Maximum connections reached, rejecting new connection');
        connection.destroy();
        _this.connectionCount--;
        return;
      }

      // Set connection timeout
      connection.setTimeout(_this.opts.connectionTimeout);
      
      // Enable keep-alive if configured
      if (_this.opts.keepAlive) {
        connection.setKeepAlive(true, 10000);
      }

      const clientAddress = connection.remoteAddress + ':' + connection.remotePort;
      console.log(`New connection from ${clientAddress} (Total: ${_this.connectionCount})`);

      // Handle connection timeout
      connection.on('timeout', function () {
        console.log(`Connection timeout for ${clientAddress}`);
        connection.destroy();
      });

      // Handle connection errors
      connection.on('error', function (err) {
        console.log(`Connection error from ${clientAddress}:`, err.message);
        // Don't crash the server, just log the error
      });

      // Create device instance
      var device = new Device(_this.getAdapter(), connection, _this);
      _this.devices.push(device);

      // Track device disconnection
      device.on('disconnected', function (deviceId) {
        console.log(`Device ${deviceId} disconnected from server list`);
        _this.connectionCount--;
        
        // Remove device from list
        const index = _this.devices.indexOf(device);
        if (index > -1) {
          _this.devices.splice(index, 1);
        }
      });

      // Once we receive data...
      connection.on('data', function (data) {
        try {
          device.emit('data', data);
        } catch (error) {
          console.error(`Error handling data from ${clientAddress}:`, error.message);
        }
      });

      // Remove the device from the list when it leaves
      connection.on('end', function () {
        console.log(`Connection ended for ${clientAddress}`);
        device.emit('disconnected');
      });

      connection.on('close', function () {
        console.log(`Connection closed for ${clientAddress}`);
        device.emit('disconnected');
      });

      // Call the callback with device and connection
      if (typeof callback === 'function') {
        try {
          callback(device, connection);
        } catch (error) {
          console.error('Error in connection callback:', error.message);
        }
      }

      device.emit('connected');
    });

    // Handle server errors
    _this.server.on('error', function (err) {
      console.error('Server error:', err.message);
      if (err.code === 'EADDRINUSE') {
        console.error(`Port ${_this.opts.port} is already in use`);
      }
    });

    // Start listening
    _this.server.listen(opts.port, function () {
      console.log(`Server listening on port ${_this.opts.port}`);
    });
  });

  /* Search a device by ID */
  this.find_device = function (deviceId) {
    for (var i in this.devices) {
      var dev = this.devices[i];
      if (dev.uid === deviceId) {
        return dev;
      }
    }
    return false;
  };

  /* SEND A MESSAGE TO DEVICE ID X */
  this.send_to = function (deviceId, msg) {
    var dev = this.find_device(deviceId);
    if (dev) {
      return dev.send(msg);
    }
    console.log(`Device ${deviceId} not found for sending message`);
    return false;
  };

  return this;
}

exports.server = Server;
exports.version = require('../package').version;